    if ((covariance == NULL) || (body_rate_rad_s == NULL) || (propagated == NULL)) {
        return ADCS_E_NULL;
    }

    if (!isfinite(dt_s) || (dt_s < 0.0) ||
        !isfinite(process_noise_rad2_s) || (process_noise_rad2_s < 0.0) ||
        !adcs_is_finite_vec3(body_rate_rad_s)) {
        *propagated = (adcs_mat3_t){{{0}}};
        return ADCS_E_RANGE;
    }

    adcs_vec3_t w = *body_rate_rad_s;
    adcs_mat3_t skew = {{{
        0.0,   -w.z,   w.y,
         w.z,    0.0,  -w.x,
        -w.y,   w.x,    0.0
    }}};

    adcs_mat3_t I = adcs_mat3_identity();
    adcs_mat3_t dt_skew = adcs_mat3_scale(&skew, dt_s);
    adcs_mat3_t F = adcs_mat3_sub(&I, &dt_skew);

    adcs_mat3_t FP = adcs_mat3_mul(&F, covariance);

    adcs_mat3_t FT = adcs_mat3_transpose(&F);
    adcs_mat3_t P_next = adcs_mat3_mul(&FP, &FT);

    double noise_term = process_noise_rad2_s * dt_s;
    P_next.m[0][0] += noise_term;
    P_next.m[1][1] += noise_term;
    P_next.m[2][2] += noise_term;

    *propagated = P_next;
    return ADCS_OK;
}

